param([string]$Results='Temp/MillionScaleExecution/funding',[switch]$TargetedOnly)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;. (Join-Path $PSScriptRoot 'ProjectLayout.ps1')
$out=Join-Path $root $Results;if(Test-Path -LiteralPath $out){throw 'Fresh output required'};New-Item -ItemType Directory -Path $out|Out-Null
$frozen=@{};foreach($relative in @('Core/CityEntities.cs','Residents/CityCoreResidents.cs','Industry/CityIndustry.cs','Economy/CityShopAccount.cs')){$name=[IO.Path]::GetFileName($relative);$path=Join-Path $out $name;$source=& git -C $root show ('791942f:Assets/Scripts/Runtime/Simulation/'+$relative);if($LASTEXITCODE -ne 0){throw 'Frozen source unavailable'};[IO.File]::WriteAllLines($path,$source);$frozen[$name]=$path}
$save=Join-Path (Split-Path $root -Parent) 'test/Temp/CityScenarios/regenerated30000-20261017/city.hcity'
foreach($version in @('old','new')){$overrides=@{};$defines='FUNDING';if($version -eq 'old'){$overrides=$frozen;$defines=''};$cases=@('funding');if(!$TargetedOnly){$cases+=@('growth')};foreach($case in $cases){$dir=Join-Path $out ($version+'/'+$case);New-Item -ItemType Directory -Path $dir -Force|Out-Null;$entry=Join-Path $PSScriptRoot $(if($case -eq 'funding'){'Diagnostics/CityFundingChecks.cs'}else{'Diagnostics/CityGrowthCandidateChecks.cs'});$binary=Build-CityDotNetHost -ProjectRoot $root -OutputDirectory $dir -Entry $entry -Defines $defines -SourceOverrides $overrides;if($case -eq 'funding'){& dotnet $binary $dir}else{& dotnet $binary $save $dir};if($LASTEXITCODE -ne 0){throw ($version+' '+$case+' failed')}}}
foreach($relative in @('funding/states.csv','funding/requests.csv')){if([IO.File]::ReadAllText((Join-Path $out ('old/'+$relative))) -cne [IO.File]::ReadAllText((Join-Path $out ('new/'+$relative)))){throw ('Full state/order differs: '+$relative)}}
if((Get-FileHash -LiteralPath (Join-Path $out 'old/funding/final.hcity')).Hash -ne (Get-FileHash -LiteralPath (Join-Path $out 'new/funding/final.hcity')).Hash){throw 'Save wire differs'}
if(!$TargetedOnly -and [IO.File]::ReadAllText((Join-Path $out 'old/growth/states.csv')) -cne [IO.File]::ReadAllText((Join-Path $out 'new/growth/states.csv'))){throw 'Growth/30k states differ'}
Write-Output 'PASS frozen791942f funding notifications: exact city/request/wire, targeted and cold tests'

if(!$TargetedOnly){$dir=Join-Path $out 'maintenance';New-Item -ItemType Directory -Path $dir|Out-Null;& dotnet (Join-Path $out 'new/funding/bin/Release/net10.0/CityModelHost.dll') $dir $save;if($LASTEXITCODE -ne 0){throw 'Funding maintenance count/cost failed'}}
